#define PI 3.14159265358979323846


vec4 Red = vec4(1,0,0,1);
vec4 Green = vec4(0,1,0,1);
vec4 Blue = vec4(0,0,1,1);
vec4 White = vec4(1,1,1,1);
int nums[6] = int[](2, 3, 5, 7, 15, 2);
float y_center = 0.35;

float wave(vec2 p, vec2 source, float spacialFreq, float phase, float v, float t)
{
    float l = length(p-source);
    return cos (phase+2.0*PI*spacialFreq*(l-t*v))/pow(l, 0.5);
}

vec2 scalerot(vec2 p, vec2 center, float angle, float scale)
{
    mat2 rot = mat2(cos(angle),-sin(angle),
               sin(angle), cos(angle));              
    return (p - center) * rot * scale + center;
}

vec2 scene (vec2 uv, float t, int num)
{
    vec2 res = vec2(0.0);
    float wavelength = 0.1;
    float v = 0.2;
    for (int i = 0; i < num; ++i)
    {
        float r = num == 1 ? 0.5 : float(i) / float(num-1);
        vec2 source = vec2(r,y_center);
        res.x += wave(uv, source, 1.0 / wavelength, r, v, t);
        res.y += smoothstep (0.05, 0.0, length (uv-source));
    }
    res.x /= float(num);
    return res;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    uv = (uv - vec2(0.5)) * vec2(1.0, iResolution.y/iResolution.x) + vec2(0.5);

    float t = iTime * 0.8 + 12.0;

    float scale = 1.0 - abs(cos(t * 0.5));
    scale = 4.0 + 10.0 * scale;
    float angle = smoothstep (0.0, 16.0, mod(t, 16.0)) * 2.0 * PI;
    uv = scalerot(uv, vec2(0.5, y_center), angle, scale);

    float numSample = mod(t, 30.0)/5.0;
    int num = nums[int(numSample)];
    int num2 = nums[int(numSample) + 1];
    vec2 r = mix(scene(uv, t,num), scene(uv,t,num2),pow(mod(numSample,1.0), 8.0));   
    fragColor = r.x > 0.0 ? sqrt(r.x) * Red :-r.x * Blue;
//    fragColor = r.x * Red;
    fragColor += r.y * White;
}
